(function () {
  var base = "/assets/erpnext/images/sgat_logo_NEO";
  function upsertIcon(rel, href, sizes, type) {
    var selector = 'link[rel="' + rel + '"]' + (sizes ? '[sizes="' + sizes + '"]' : '');
    var node = document.head.querySelector(selector);
    if (!node) {
      node = document.createElement("link");
      node.rel = rel;
      if (sizes) node.sizes = sizes;
      document.head.appendChild(node);
    }
    node.href = href;
    if (type) node.type = type;
  }
  upsertIcon("icon", base + "/favicon.ico", null, "image/x-icon");
  upsertIcon("icon", base + "/favicon-32x32.png", "32x32", "image/png");
  upsertIcon("icon", base + "/favicon-16x16.png", "16x16", "image/png");
  upsertIcon("apple-touch-icon", base + "/apple-touch-icon.png", null, "image/png");
})();

